'use client';

import { FormEvent, useEffect, useState } from 'react';
import { createTelephoneCall, getProspects, getTelephoneCalls } from '@/lib/api';

type Prospect = { id: number; name: string; phone?: string; company?: string };
type Call = { id: number; to_number: string; status: string; duration_seconds: number | null; created_at: string; prospect_name?: string };

export default function TelephoneAIPage() {
  const [prospects, setProspects] = useState<Prospect[]>([]); const [calls, setCalls] = useState<Call[]>([]); const [prospectId, setProspectId] = useState(''); const [to, setTo] = useState(''); const [script, setScript] = useState('Hello. This is a call from OutreachAI. We would like to speak with you about how we may help your business. Please contact us at your convenience.'); const [notice, setNotice] = useState(''); const [saving, setSaving] = useState(false); const [configured, setConfigured] = useState(false);
  const load = async () => { const [callData, prospectData] = await Promise.all([getTelephoneCalls(), getProspects()]); if (callData.error) setNotice(callData.error); else { setCalls(callData.calls || []); setConfigured(Boolean(callData.configured)); } if (!prospectData.error) setProspects(prospectData || []); };
  useEffect(() => { load(); }, []);
  const chooseProspect = (value: string) => { setProspectId(value); const prospect = prospects.find((item) => String(item.id) === value); setTo(prospect?.phone || ''); };
  const submit = async (event: FormEvent) => { event.preventDefault(); setSaving(true); setNotice(''); const data = await createTelephoneCall({ prospect_id: Number(prospectId), to, script }); setSaving(false); if (data.error) { setNotice(data.error); return; } setNotice('AI call submitted to Twilio. Conversation and call status are now live.'); load(); };
  return <main className="min-h-screen bg-gray-950 p-6 text-white"><div className="mx-auto max-w-6xl"><p className="text-sm font-semibold uppercase tracking-[.2em] text-blue-300">Twilio Voice</p><h1 className="mt-2 text-2xl font-semibold">Telephone outreach</h1><p className="mt-2 max-w-3xl text-sm leading-6 text-gray-400">Place consent-based outbound calls using your Twilio number. Each call plays the approved script and Twilio returns live delivery status. Enterprise plan access is required.</p>{!configured && <div className="mt-5 rounded-xl border border-amber-400/30 bg-amber-500/10 p-4 text-sm text-amber-100">Twilio is not configured yet. Add <code>TWILIO_ACCOUNT_SID</code>, <code>TWILIO_AUTH_TOKEN</code>, <code>TWILIO_PHONE_NUMBER</code>, and a public HTTPS <code>BACKEND_URL</code> to the deployed backend environment.</div>}<div className="mt-8 grid gap-7 lg:grid-cols-[.9fr_1.1fr]"><form onSubmit={submit} className="rounded-xl border border-gray-700 bg-gray-800 p-5"><h2 className="font-medium">Start an outbound call</h2><label className="mt-4 block text-xs text-gray-400">Prospect with telephone consent</label><select required value={prospectId} onChange={(event) => chooseProspect(event.target.value)} className="mt-1 w-full rounded-lg border border-gray-600 bg-gray-900 px-3 py-2 text-sm"><option value="">Choose a consented prospect</option>{prospects.map((prospect) => <option key={prospect.id} value={prospect.id}>{prospect.name}{prospect.company ? ` — ${prospect.company}` : ''}</option>)}</select><label className="mt-4 block text-xs text-gray-400">Phone number from the selected prospect</label><input readOnly value={to} placeholder="Add an E.164 phone number to this prospect" className="mt-1 w-full rounded-lg border border-gray-600 bg-gray-900 px-3 py-2 text-sm text-gray-300"/><label className="mt-4 block text-xs text-gray-400">Approved call script</label><textarea required maxLength={2000} value={script} onChange={(event) => setScript(event.target.value)} rows={9} className="mt-1 w-full rounded-lg border border-gray-600 bg-gray-900 px-3 py-2 text-sm"/><p className="mt-2 text-xs text-gray-500">{script.length}/2,000 characters. The server verifies recorded telephone consent before contacting the selected prospect.</p><button disabled={saving || !configured} className="mt-4 rounded-lg bg-blue-600 px-4 py-2 text-sm font-medium hover:bg-blue-500 disabled:cursor-not-allowed disabled:opacity-50">{saving ? 'Submitting…' : 'Place Twilio call'}</button>{notice && <p className="mt-4 rounded-lg border border-blue-400/30 bg-blue-500/10 px-3 py-2 text-sm text-blue-100">{notice}</p>}</form><section className="rounded-xl border border-gray-700 bg-gray-800 p-5"><h2 className="font-medium">Call history</h2><div className="mt-4 space-y-3">{calls.length === 0 ? <p className="text-sm text-gray-400">No calls placed yet.</p> : calls.map((call) => <article key={call.id} className="rounded-lg border border-gray-700 bg-gray-900/60 p-4"><div className="flex flex-wrap justify-between gap-2"><div><p className="font-medium">{call.prospect_name || call.to_number}</p><p className="text-xs text-gray-400">{call.to_number}</p></div><span className="text-sm capitalize text-blue-200">{call.status}</span></div><p className="mt-2 text-xs text-gray-500">{new Date(call.created_at).toLocaleString()}{call.duration_seconds !== null ? ` · ${call.duration_seconds}s` : ''}</p></article>)}</div></section></div></div></main>;
}
